local function alive() -- line: 37
    -- upvalues: LocalPlayer (copy)
    local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    if Humanoid then
        if not (Humanoid.Health > 0) then
            Character = false
        end
    else
        Character = Humanoid
    end

    return Character, Humanoid
end

local function tryBite() -- line: 43
    -- upvalues: Remotes (copy), LegAnimator (copy), Effects (copy), TargetIndicator (copy), t1 (copy), LocalPlayer (copy)
    local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    if Humanoid then
        if not (Humanoid.Health > 0) then
            Character = false
        end
    else
        Character = Humanoid
    end

    if Character and not t1.Blocked and not Character:GetAttribute("Stunned") then
        local elapsed = os.clock()

        if elapsed < t1.NextBite then
            return
        end

        t1.BiteCooldown = 1 / ((LocalPlayer:GetAttribute("AttackSpeed") or 1) * (LocalPlayer:GetAttribute("AttackSpeedMult") or 1))
        t1.NextBite = elapsed + t1.BiteCooldown

        local Current = TargetIndicator.Current

        Remotes.Attack:FireServer(Current)

        local HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")
        local v7 = Current and (Current.PrimaryPart or Current:FindFirstChild("HumanoidRootPart"))

        if HumanoidRootPart and v7 then
            local v8 = (v7.Position - HumanoidRootPart.Position) * Vector3.new(1, 0, 1)

            if v8.Magnitude > 0.5 then
                HumanoidRootPart.CFrame = CFrame.lookAt(HumanoidRootPart.Position, HumanoidRootPart.Position + v8.Unit)
            end
        end

        LegAnimator.PlayLocalAttack(Character)
        TargetIndicator.Pulse()
        Effects.AttackSound(Current)
    end
end

